BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE tipo_usuario AS ENUM ('ADMIN','GERENTE','ATENDENTE','COZINHA','ENTREGADOR');
CREATE TYPE status_whatsapp AS ENUM ('DESCONECTADO','CONECTANDO','QR_CODE','CONECTADO','ERRO');
CREATE TYPE tipo_produto AS ENUM ('PRODUTO','COMBO');
CREATE TABLE empresas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),razao_social VARCHAR(150) NOT NULL,nome_fantasia VARCHAR(150) NOT NULL,documento VARCHAR(20) UNIQUE,telefone VARCHAR(20),email VARCHAR(150),timezone VARCHAR(50) NOT NULL DEFAULT 'America/Sao_Paulo',ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE usuarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),nome VARCHAR(120) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,senha_hash VARCHAR(255) NOT NULL,tipo tipo_usuario NOT NULL DEFAULT 'ATENDENTE',ativo BOOLEAN NOT NULL DEFAULT TRUE,ultimo_acesso TIMESTAMPTZ,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE usuario_empresas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),usuario_id UUID NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,principal BOOLEAN NOT NULL DEFAULT FALSE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(usuario_id,empresa_id));
CREATE INDEX idx_usuario_empresas_empresa ON usuario_empresas(empresa_id);
CREATE TABLE whatsapp_sessoes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,nome VARCHAR(80) NOT NULL,client_id VARCHAR(100) NOT NULL,telefone VARCHAR(20),status status_whatsapp NOT NULL DEFAULT 'DESCONECTADO',qr_code TEXT,ultima_conexao TIMESTAMPTZ,ultimo_erro TEXT,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(empresa_id,client_id));
CREATE INDEX idx_whatsapp_sessoes_empresa_status ON whatsapp_sessoes(empresa_id,status);
CREATE TABLE clientes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,nome VARCHAR(120),telefone VARCHAR(20) NOT NULL,whatsapp_id VARCHAR(100),email VARCHAR(150),observacoes TEXT,bloqueado BOOLEAN NOT NULL DEFAULT FALSE,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(empresa_id,telefone));
CREATE INDEX idx_clientes_empresa_nome ON clientes(empresa_id,nome);
CREATE TABLE enderecos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),cliente_id UUID NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,apelido VARCHAR(50),cep VARCHAR(10),logradouro VARCHAR(150) NOT NULL,numero VARCHAR(20) NOT NULL,complemento VARCHAR(100),bairro VARCHAR(100) NOT NULL,cidade VARCHAR(100) NOT NULL,uf CHAR(2) NOT NULL,referencia VARCHAR(255),latitude NUMERIC(10,7),longitude NUMERIC(10,7),principal BOOLEAN NOT NULL DEFAULT FALSE,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_enderecos_cliente_principal ON enderecos(cliente_id,principal);
CREATE TABLE categorias (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,nome VARCHAR(100) NOT NULL,descricao VARCHAR(255),imagem_url TEXT,ordem INTEGER NOT NULL DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(empresa_id,nome));
CREATE INDEX idx_categorias_empresa_ativo_ordem ON categorias(empresa_id,ativo,ordem);
CREATE TABLE produtos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,categoria_id UUID NOT NULL REFERENCES categorias(id) ON DELETE RESTRICT,tipo tipo_produto NOT NULL DEFAULT 'PRODUTO',nome VARCHAR(150) NOT NULL,descricao TEXT,preco NUMERIC(12,2) NOT NULL CHECK(preco>=0),preco_promocional NUMERIC(12,2) CHECK(preco_promocional IS NULL OR preco_promocional>=0),imagem_url TEXT,codigo_interno VARCHAR(50),disponivel BOOLEAN NOT NULL DEFAULT TRUE,destaque BOOLEAN NOT NULL DEFAULT FALSE,ordem INTEGER NOT NULL DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(empresa_id,codigo_interno));
CREATE INDEX idx_produtos_empresa_categoria ON produtos(empresa_id,categoria_id,ativo,disponivel);
CREATE TABLE produto_variacoes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),produto_id UUID NOT NULL REFERENCES produtos(id) ON DELETE CASCADE,nome VARCHAR(100) NOT NULL,preco NUMERIC(12,2) NOT NULL CHECK(preco>=0),ordem INTEGER NOT NULL DEFAULT 0,disponivel BOOLEAN NOT NULL DEFAULT TRUE,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(produto_id,nome));
CREATE TABLE produto_adicionais (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),produto_id UUID NOT NULL REFERENCES produtos(id) ON DELETE CASCADE,nome VARCHAR(100) NOT NULL,preco NUMERIC(12,2) NOT NULL CHECK(preco>=0),limite INTEGER NOT NULL DEFAULT 1 CHECK(limite>0),obrigatorio BOOLEAN NOT NULL DEFAULT FALSE,ordem INTEGER NOT NULL DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(produto_id,nome));
CREATE OR REPLACE FUNCTION atualizar_atualizado_em() RETURNS TRIGGER AS $$ BEGIN NEW.atualizado_em=CURRENT_TIMESTAMP; RETURN NEW; END; $$ LANGUAGE plpgsql;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['empresas','usuarios','whatsapp_sessoes','clientes','enderecos','categorias','produtos','produto_variacoes','produto_adicionais'] LOOP EXECUTE format('CREATE TRIGGER trg_%I_atualizado_em BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION atualizar_atualizado_em()',t,t); END LOOP; END $$;
COMMIT;
